import {
  MapContainer,
  TileLayer,
  Polyline,
  Marker,
  Tooltip,
} from "react-leaflet";
import { useEffect, useState } from "react";
import axios from "axios";
import L from "leaflet";

// 🔥 Fix marker icons
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon-2x.png",
  iconUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon.png",
  shadowUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-shadow.png",
});

const MAX_POINTS = 500;

function App() {
  const [data, setData] = useState([]);
  const [filtered, setFiltered] = useState([]);
  const [path, setPath] = useState([]);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);

  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");

  // 🚀 Fetch data
  useEffect(() => {
    fetchData();
  }, []);

  const fetchData = async () => {
    try {
      const res = await axios.get("http://localhost:3000/path");

      const formatted = res.data
        .filter(d =>
          d &&
          d.location &&
          d.location.coordinates &&
          d.location.coordinates.length === 2 &&
          d.location.coordinates[0] !== 0 &&
          d.location.coordinates[1] !== 0
        )
        .slice(-MAX_POINTS)
        .map((d, i) => ({
          lat: d.location.coordinates[1],
          lon: d.location.coordinates[0],
          alt: d.alt || 0,
          timestamp: new Date(d.timestamp),
          index: i,
        }));

      setData(formatted);
      setFiltered(formatted);

      if (formatted.length > 0) {
        setPath([formatted[0]]);
      }

    } catch (err) {
      console.error("Fetch error:", err);
    }
  };

  // 🎯 Apply time filter
 const applyFilter = () => {
  if (!startTime || !endTime) {
    alert("Please select both start and end time");
    return;
  }

  // 🔥 Convert local input to proper Date
  const start = new Date(startTime);
  const end = new Date(endTime);

  console.log("START:", start);
  console.log("END:", end);

  // ✅ Filter safely
  const filteredData = data.filter(d => {
    if (!d.timestamp) return false;

    return d.timestamp >= start && d.timestamp <= end;
  });

  console.log("FILTERED:", filteredData.length);

  if (filteredData.length === 0) {
    alert("No data found in selected time range");
    return;
  }

  setFiltered(filteredData);
  setPath([filteredData[0]]);
  setCurrentIndex(0);
  setIsPlaying(false);
};

  // 🎬 Playback
  useEffect(() => {
    if (!isPlaying || filtered.length === 0) return;

    const interval = setInterval(() => {
      setCurrentIndex(prev => {
        if (prev >= filtered.length - 1) {
          clearInterval(interval);
          setIsPlaying(false);
          return prev;
        }

        setPath(filtered.slice(0, prev + 1));
        return prev + 1;
      });
    }, 200);

    return () => clearInterval(interval);
  }, [isPlaying, filtered]);

  // 🎯 Slider control
  const handleSlider = (e) => {
    const index = Number(e.target.value);
    setCurrentIndex(index);
    setPath(filtered.slice(0, index + 1));
  };

  return (
    <div style={{ padding: "10px" }}>
      <h2>🚁 Drone Timeline Control (Timestamp Based)</h2>

      {/* ⏱️ TIME FILTER */}
      <div style={{ marginBottom: "10px" }}>
        <label>Start: </label>
        <input
          type="datetime-local"
          onChange={(e) => setStartTime(e.target.value)}
        />

        <label style={{ marginLeft: "10px" }}>End: </label>
        <input
          type="datetime-local"
          onChange={(e) => setEndTime(e.target.value)}
        />

        <button onClick={applyFilter} style={{ marginLeft: "10px" }}>
          Apply
        </button>
      </div>

      {/* 🎮 CONTROLS */}
      <div style={{ marginBottom: "10px" }}>
        <button onClick={() => setIsPlaying(true)}>▶ Play</button>
        <button onClick={() => setIsPlaying(false)}>⏸ Pause</button>

        <input
          type="range"
          min="0"
          max={filtered.length > 0 ? filtered.length - 1 : 0}
          value={currentIndex}
          onChange={handleSlider}
          style={{ width: "60%", marginLeft: "10px" }}
        />

        <span style={{ marginLeft: "10px" }}>
          {filtered[currentIndex]?.timestamp?.toLocaleString()}
        </span>
      </div>

      {/* 🗺️ MAP */}
      <MapContainer
        center={[12.9716, 77.5946]}
        zoom={18}
        style={{ height: "70vh", width: "100%" }}
      >
        <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />

        {/* 🔵 Path */}
        <Polyline
          positions={path
            .filter(p => p && p.lat && p.lon)
            .map(p => [p.lat, p.lon])}
          color="cyan"
        />

        {/* 📍 Drone */}
        {path.length > 0 &&
          path[path.length - 1]?.lat && (
            <Marker
              position={[
                path[path.length - 1].lat,
                path[path.length - 1].lon,
              ]}
            >
              <Tooltip permanent>
                Alt: {path[path.length - 1].alt?.toFixed(2)} m
              </Tooltip>
            </Marker>
          )}
      </MapContainer>
    </div>
  );
}

export default App;
